public enum ClientRuntimeScreenKind: String, Equatable, Sendable {
    case dock
    case threadDetail
    case archive
    case hosts
    case connectivity
}

public struct ClientRuntimeScreenFactory: Equatable, Sendable {
    public let kind: ClientRuntimeScreenKind
    public let hostCount: Int
    public let usesRuntimeConnectivitySink: Bool

    public init(
        kind: ClientRuntimeScreenKind,
        hostCount: Int,
        usesRuntimeConnectivitySink: Bool
    ) {
        self.kind = kind
        self.hostCount = hostCount
        self.usesRuntimeConnectivitySink = usesRuntimeConnectivitySink
    }
}

public struct ClientRuntime: Sendable {
    public let registry: HostRegistry
    public let connectivityEventSink: ConnectivityEventSink

    private let now: @Sendable () -> Date

    public init(
        registry: HostRegistry,
        connectivityEventSink: ConnectivityEventSink = ConnectivityEventSink(),
        now: @escaping @Sendable () -> Date = Date.init
    ) {
        self.registry = registry
        self.connectivityEventSink = connectivityEventSink
        self.now = now
    }

    public func makeDockScreenStoreFactory() -> ClientRuntimeScreenFactory {
        screenFactory(kind: .dock)
    }

    @MainActor
    public func makeDockStore(
        streamClient: any ThreadCardStreamConnecting = AppServerThreadCardStreamClient(),
        archiver: any ThreadArchiveCommanding = AppServerThreadCommandClient(),
        metadataStore: any LocalThreadMetadataStoring = FileLocalThreadMetadataStore(),
        streamReconnectDelay: Duration = CodexDockConstants.Dock.autoRefreshInterval
    ) -> DockStore {
        DockStore(
            registry: registry,
            streamClient: streamClient,
            archiver: archiver,
            metadataStore: metadataStore,
            streamReconnectDelay: streamReconnectDelay,
            connectivityEventSink: connectivityEventSink,
            now: now
        )
    }

    public func makeThreadDetailScreenStoreFactory() -> ClientRuntimeScreenFactory {
        screenFactory(kind: .threadDetail)
    }

    @MainActor
    public func makeThreadDetailStore(
        host: DockHostConfiguration,
        row: DockRowViewModel,
        factory: any ThreadDetailSessionMaking = AppServerThreadDetailSessionFactory(),
        realtimeTranscriptionService: (any RealtimeTranscriptionServicing)? = nil,
        liveVoiceCaptureController: (any LiveVoiceCaptureControlling)? = nil,
        lifecycleCoordinator: AppLifecycleCoordinator? = nil,
        connectivityReporter: (any AppConnectivityReporting)? = nil,
        hostIdentityResolver: DockHostIdentityResolver? = nil
    ) -> ThreadDetailStore {
        ThreadDetailStore(
            host: host,
            row: row,
            factory: factory,
            realtimeTranscriptionService: realtimeTranscriptionService,
            liveVoiceCaptureController: liveVoiceCaptureController,
            lifecycleCoordinator: lifecycleCoordinator,
            connectivityReporter: connectivityReporter,
            connectivityEventSink: connectivityEventSink,
            hostIdentityResolver: hostIdentityResolver,
            now: now
        )
    }

    public func makeArchiveScreenStoreFactory() -> ClientRuntimeScreenFactory {
        screenFactory(kind: .archive)
    }

    @MainActor
    public func makeArchiveStore(
        streamClient: any ThreadCardStreamConnecting = AppServerThreadCardStreamClient(view: .archive),
        archiver: any ThreadArchiveCommanding = AppServerThreadCommandClient(),
        metadataStore: any LocalThreadMetadataStoring = FileLocalThreadMetadataStore()
    ) -> ArchiveStore {
        ArchiveStore(
            registry: registry,
            streamClient: streamClient,
            archiver: archiver,
            metadataStore: metadataStore,
            connectivityEventSink: connectivityEventSink,
            now: now
        )
    }

    public func makeHostSettingsScreenStoreFactory() -> ClientRuntimeScreenFactory {
        screenFactory(kind: .hosts)
    }

    @MainActor
    public func makeHostSettingsStore(
        tester: any HostConnectionTesting = CardStreamHostConnectionTester(),
        configurationStore: any LocalDockConfigurationStoring = FileLocalDockConfigurationStore()
    ) -> HostSettingsStore {
        HostSettingsStore(
            registry: registry,
            tester: tester,
            configurationStore: configurationStore,
            connectivityEventSink: connectivityEventSink,
            now: now
        )
    }

    public func makeConnectivityScreenStoreFactory() -> ClientRuntimeScreenFactory {
        screenFactory(kind: .connectivity)
    }

    @MainActor
    public func makeConnectivityScreenStore() -> ConnectivityScreenStore {
        ConnectivityScreenStore(
            registry: registry,
            eventSink: connectivityEventSink,
            now: now
        )
    }

    public func currentDate() -> Date {
        now()
    }

    private func screenFactory(kind: ClientRuntimeScreenKind) -> ClientRuntimeScreenFactory {
        ClientRuntimeScreenFactory(
            kind: kind,
            hostCount: registry.hosts.count,
            usesRuntimeConnectivitySink: true
        )
    }
}

import Foundation
import OSLog

@MainActor
protocol ThreadCardStreamLifecycleDelegate: AnyObject {
    func cardStreamLifecycleMarkChecking(host: DockHostConfiguration) async
    func cardStreamLifecycleMarkFailure(_ failure: DockRequestFailure, host: DockHostConfiguration) async
    func cardStreamLifecycleApplySnapshot(
        _ update: ThreadCardStreamUpdateDTO,
        host: DockHostConfiguration
    ) async -> ThreadCardTableApplyResult
    func cardStreamLifecycleApplyUpdate(
        _ update: ThreadCardStreamUpdateDTO,
        host: DockHostConfiguration
    ) async -> ThreadCardTableApplyResult
    func cardStreamLifecycleRowCount(for host: DockHostConfiguration) async -> Int
    func cardStreamLifecyclePublishSnapshot() async
    func cardStreamLifecycleMigrateMetadataHostAliases() async
}

@MainActor
final class ThreadCardStreamLifecycle {
    private let view: ThreadCardStreamView
    private let streamClient: any ThreadCardStreamConnecting
    private let streamReconnectDelay: Duration
    private let streamHeartbeatTimeout: Duration
    private let logger: Logger
    private let logName: String
    private weak var delegate: (any ThreadCardStreamLifecycleDelegate)?

    private var streamConnections: [String: any ThreadCardStreamConnection] = [:]
    private var streamTasks: [String: Task<Void, Never>] = [:]
    private var streamHeartbeatTasks: [String: Task<Void, Never>] = [:]
    private var streamHeartbeatTokens: [String: UUID] = [:]

    init(
        view: ThreadCardStreamView,
        streamClient: any ThreadCardStreamConnecting,
        streamReconnectDelay: Duration,
        streamHeartbeatTimeout: Duration,
        logger: Logger,
        logName: String,
        delegate: any ThreadCardStreamLifecycleDelegate
    ) {
        self.view = view
        self.streamClient = streamClient
        self.streamReconnectDelay = streamReconnectDelay
        self.streamHeartbeatTimeout = streamHeartbeatTimeout
        self.logger = logger
        self.logName = logName
        self.delegate = delegate
    }

    deinit {
        streamTasks.values.forEach { $0.cancel() }
        streamHeartbeatTasks.values.forEach { $0.cancel() }
    }

    func synchronizeStreams(hosts: [DockHostConfiguration]) async {
        let validHostIDs = Set(hosts.map(\.id))
        for hostID in streamConnections.keys where !validHostIDs.contains(hostID) {
            streamTasks[hostID]?.cancel()
            streamTasks[hostID] = nil
            streamHeartbeatTasks[hostID]?.cancel()
            streamHeartbeatTasks[hostID] = nil
            streamHeartbeatTokens[hostID] = nil
            let connection = streamConnections.removeValue(forKey: hostID)
            await connection?.close()
        }

        for host in hosts {
            if let connection = streamConnections[host.id] {
                await resync(host: host, connection: connection)
            } else {
                await openStream(host: host)
            }
        }
    }

    func closeStreams() async {
        streamTasks.values.forEach { $0.cancel() }
        streamTasks = [:]
        streamHeartbeatTasks.values.forEach { $0.cancel() }
        streamHeartbeatTasks = [:]
        streamHeartbeatTokens = [:]
        let connections = streamConnections
        streamConnections = [:]
        for connection in connections.values {
            await connection.close()
        }
    }

    private func openStream(host: DockHostConfiguration) async {
        guard let delegate else {
            return
        }

        await delegate.cardStreamLifecycleMarkChecking(host: host)
        await delegate.cardStreamLifecyclePublishSnapshot()
        var openedConnection: (any ThreadCardStreamConnection)?
        do {
            let connection = try await streamClient.connect(to: host)
            openedConnection = connection
            streamConnections[host.id] = connection
            let snapshot = try await connection.subscribe()
            try await applySubscribedSnapshot(snapshot, host: host, connection: connection)
            recordStreamActivity(host: host, connection: connection)
            startUpdateTask(host: host, connection: connection)
            await delegate.cardStreamLifecycleMigrateMetadataHostAliases()
            await delegate.cardStreamLifecyclePublishSnapshot()
        } catch {
            streamTasks[host.id]?.cancel()
            streamTasks[host.id] = nil
            streamHeartbeatTasks[host.id]?.cancel()
            streamHeartbeatTasks[host.id] = nil
            streamHeartbeatTokens[host.id] = nil
            streamConnections[host.id] = nil
            await openedConnection?.close()
            logger.warning("\(self.logName, privacy: .public) stream open failed view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
            await delegate.cardStreamLifecycleMarkFailure(Self.mapRequestFailure(error), host: host)
            await delegate.cardStreamLifecyclePublishSnapshot()
        }
    }

    private func resync(host: DockHostConfiguration, connection: any ThreadCardStreamConnection) async {
        guard let delegate else {
            return
        }

        do {
            let snapshot = try await connection.resync()
            try await applyResyncSnapshot(snapshot, host: host)
            await delegate.cardStreamLifecycleMigrateMetadataHostAliases()
            await delegate.cardStreamLifecyclePublishSnapshot()
            let rowCount = await delegate.cardStreamLifecycleRowCount(for: host)
            logger.notice("\(self.logName, privacy: .public) stream resync finished view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) seq=\(snapshot.seq, privacy: .public) rows=\(rowCount, privacy: .public)")
        } catch {
            logger.warning("\(self.logName, privacy: .public) stream resync failed view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
            await delegate.cardStreamLifecycleMarkFailure(Self.mapRequestFailure(error), host: host)
            await delegate.cardStreamLifecyclePublishSnapshot()
        }
    }

    private func startUpdateTask(host: DockHostConfiguration, connection: any ThreadCardStreamConnection) {
        streamTasks[host.id]?.cancel()
        streamTasks[host.id] = Task { [weak self, host, connection] in
            do {
                for try await update in connection.updates() {
                    await self?.handleStreamUpdate(update, host: host, connection: connection)
                }
                if !Task.isCancelled {
                    await self?.handleStreamFailure(
                        DockRequestFailure.offline("Relay stream closed"),
                        host: host,
                        connection: connection
                    )
                }
            } catch is CancellationError {
                return
            } catch {
                await self?.handleStreamFailure(error, host: host, connection: connection)
            }
        }
    }

    private func recordStreamActivity(host: DockHostConfiguration, connection: any ThreadCardStreamConnection) {
        let token = UUID()
        streamHeartbeatTokens[host.id] = token
        streamHeartbeatTasks[host.id]?.cancel()
        streamHeartbeatTasks[host.id] = Task { [weak self, host, connection, token] in
            guard let self else {
                return
            }
            let timeout = streamHeartbeatTimeout
            do {
                try await Task.sleep(for: timeout)
            } catch {
                return
            }
            await self.handleHeartbeatTimeout(host: host, connection: connection, token: token)
        }
    }

    private func handleHeartbeatTimeout(
        host: DockHostConfiguration,
        connection: any ThreadCardStreamConnection,
        token: UUID
    ) async {
        guard streamHeartbeatTokens[host.id] == token else {
            return
        }
        logger.warning("\(self.logName, privacy: .public) stream heartbeat timed out view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public)")
        await handleStreamFailure(
            DockRequestFailure.offline("Relay stream heartbeat timed out"),
            host: host,
            connection: connection
        )
    }

    private func handleStreamUpdate(
        _ update: ThreadCardStreamUpdateDTO,
        host: DockHostConfiguration,
        connection: any ThreadCardStreamConnection
    ) async {
        guard let delegate else {
            return
        }

        recordStreamActivity(host: host, connection: connection)
        let result = await delegate.cardStreamLifecycleApplyUpdate(update, host: host)
        if case .needsResync(let reason) = result {
            logger.warning("\(self.logName, privacy: .public) stream resync needed view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) reason=\(reason.rawValue, privacy: .public) update_kind=\(update.kind.rawValue, privacy: .public) seq=\(update.seq, privacy: .public)")
            await resync(host: host, connection: connection)
        } else {
            await delegate.cardStreamLifecycleMigrateMetadataHostAliases()
            await delegate.cardStreamLifecyclePublishSnapshot()
            let rowCount = await delegate.cardStreamLifecycleRowCount(for: host)
            logger.info("\(self.logName, privacy: .public) stream update applied view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) update_kind=\(update.kind.rawValue, privacy: .public) seq=\(update.seq, privacy: .public) rows=\(rowCount, privacy: .public)")
            let freshness = update.freshness
            if freshness.status != .fresh,
               rowCount > 0 {
                logger.notice("\(self.logName, privacy: .public) stream rows retained view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) freshness=\(freshness.status.rawValue, privacy: .public) rows=\(rowCount, privacy: .public)")
            }
        }
    }

    private func applySubscribedSnapshot(
        _ snapshot: ThreadCardStreamUpdateDTO,
        host: DockHostConfiguration,
        connection: any ThreadCardStreamConnection
    ) async throws {
        guard let delegate else {
            return
        }

        switch await delegate.cardStreamLifecycleApplySnapshot(snapshot, host: host) {
        case .applied:
            return
        case .needsResync(let reason):
            logger.warning("\(self.logName, privacy: .public) stream subscribe snapshot rejected view=\(self.view.rawValue, privacy: .public) host_id=\(host.id, privacy: .public) reason=\(reason.rawValue, privacy: .public) seq=\(snapshot.seq, privacy: .public)")
            let resynced = try await connection.resync()
            try await applyResyncSnapshot(resynced, host: host)
        }
    }

    private func applyResyncSnapshot(
        _ snapshot: ThreadCardStreamUpdateDTO,
        host: DockHostConfiguration
    ) async throws {
        guard let delegate else {
            return
        }

        switch await delegate.cardStreamLifecycleApplySnapshot(snapshot, host: host) {
        case .applied:
            return
        case .needsResync(let reason):
            throw DockRequestFailure.error("\(logName.capitalized) stream resync returned incompatible data (\(reason.rawValue)).")
        }
    }

import Foundation

enum ThreadCardTableResyncReason: String, Equatable, Sendable {
    case schemaMismatch
    case streamContract
    case epochMismatch
    case sequenceGap
    case staleGeneration
}

enum ThreadCardTableApplyResult: Equatable, Sendable {
    case applied
    case needsResync(ThreadCardTableResyncReason)
}

struct ThreadCardTable: Equatable, Sendable {
    private enum ProjectionEnvelope {
        static let schemaVersion = 1
        static let identityVersion = 1
        static let engineVersion = 1
        static let rowRole = "threadCard"
        static let scope = "view"
        static let order = "displayOrderKeyAscending"
    }

    private struct HostStreamState: Equatable, Sendable {
        var epoch: String?
        var seq: Int64
        var sourceHostID: String?
        var status: DockHostLoadStatus
        var freshness: DockStreamFreshnessDTO?
        var complete: Bool
        var totalRows: Int?
        var window: DockStreamWindowDTO?
        var cardsByID: [String: DockThreadCardDTO]

        init(status: DockHostLoadStatus = .checking) {
            self.epoch = nil
            self.seq = 0
            self.status = status
            self.freshness = nil
            self.complete = false
            self.totalRows = nil
            self.window = nil
            self.cardsByID = [:]
        }
    }

    private let expectedView: ThreadCardStreamView
    private var statesByHostID: [String: HostStreamState] = [:]

    init(expectedView: ThreadCardStreamView = .dock) {
        self.expectedView = expectedView
    }

    mutating func reset(hosts: [DockHostConfiguration]) {
        statesByHostID = Dictionary(
            uniqueKeysWithValues: hosts.map { host in
                (host.id, HostStreamState())
            }
        )
    }

    mutating func ensureHosts(_ hosts: [DockHostConfiguration]) {
        let validHostIDs = Set(hosts.map(\.id))
        statesByHostID = statesByHostID.filter { validHostIDs.contains($0.key) }
        for host in hosts where statesByHostID[host.id] == nil {
            statesByHostID[host.id] = HostStreamState()
        }
    }

    mutating func markChecking(host: DockHostConfiguration) {
        var state = statesByHostID[host.id] ?? HostStreamState()
        let rowCount = state.cardsByID.count
        state.status = rowCount > 0
            ? .degraded(rowCount: rowCount, message: "Reconnecting")
            : .checking
        statesByHostID[host.id] = state
    }

    mutating func markFailure(_ failure: DockRequestFailure, host: DockHostConfiguration) {
        var state = statesByHostID[host.id] ?? HostStreamState()
        let message = failure.localizedDescription
        let rowCount = state.cardsByID.count
        switch failure {
        case .offline:
            state.status = rowCount > 0 ? .degraded(rowCount: rowCount, message: "Offline: \(message)") : .offline(message)
            state.freshness = DockStreamFreshnessDTO(status: .offline, lastError: message)
        case .error:
            state.status = rowCount > 0 ? .degraded(rowCount: rowCount, message: message) : .error(message)
            state.freshness = DockStreamFreshnessDTO(status: .error, lastError: message)
        }
        statesByHostID[host.id] = state
    }

    mutating func applySnapshot(_ update: ThreadCardStreamUpdateDTO, host: DockHostConfiguration) -> ThreadCardTableApplyResult {
        guard acceptsSchemaVersion(update.schemaVersion) else {
            return .needsResync(.schemaMismatch)
        }
        guard acceptsStreamContract(update) else {
            return .needsResync(.streamContract)
        }

        var state = statesByHostID[host.id] ?? HostStreamState()
        if state.epoch == nil || state.epoch == update.epoch {
        }
        state.epoch = update.epoch
        state.seq = update.seq
        state.sourceHostID = update.sourceHostID
        state.freshness = update.freshness
        state.complete = update.complete ?? false
        state.totalRows = update.totalRows
        state.window = update.window
        state.cardsByID = Dictionary(
            uniqueKeysWithValues: (update.rows ?? [])
                .filter(\.isAppFacingHumanThreadCard)
                .map { card in
                    (card.projectionStorageKey, card)
                }
        )
        state.status = hostStatus(
            freshness: update.freshness,
            rowCount: state.cardsByID.count,
            complete: state.complete,
            totalRows: state.totalRows,
            window: state.window
        )
        statesByHostID[host.id] = state
        return .applied
    }

    mutating func applyUpdate(_ update: ThreadCardStreamUpdateDTO, host: DockHostConfiguration) -> ThreadCardTableApplyResult {
        guard update.kind != .snapshot else {
            return applySnapshot(update, host: host)
        }

        guard acceptsSchemaVersion(update.schemaVersion) else {
            return .needsResync(.schemaMismatch)
        }
        guard var state = statesByHostID[host.id],
              state.epoch == update.epoch else {
            return .needsResync(.epochMismatch)
        }
        guard acceptsStreamContract(update, expectedSourceHostID: state.sourceHostID) else {
            return .needsResync(.streamContract)
        }
        guard acceptsProjectionSourceContinuity(update.rows ?? [], existingCardsByID: state.cardsByID) else {
            return .needsResync(.streamContract)
        }
        switch update.kind {
        case .heartbeat:
            guard state.seq == update.seq else {
                return .needsResync(.sequenceGap)
            }
        case .upsert, .delete:
            guard update.seq == state.seq + 1 else {
                return .needsResync(.sequenceGap)
            }
            for projectionID in update.projectionIDs ?? [] {
                state.cardsByID.removeValue(forKey: projectionID)
            }
            for card in (update.rows ?? []).filter(\.isAppFacingHumanThreadCard) {
                state.cardsByID[card.projectionStorageKey] = card
            }
            state.seq = update.seq
        case .resyncRequired:
            return .needsResync(.streamContract)
        case .snapshot:
            break
        }

        state.freshness = update.freshness
        state.complete = update.complete ?? state.complete
        state.totalRows = update.totalRows ?? state.totalRows
        state.window = update.window ?? state.window
        state.status = hostStatus(
            freshness: state.freshness,
            rowCount: state.cardsByID.count,
            complete: state.complete,
            totalRows: state.totalRows,
            window: state.window
        )
        statesByHostID[host.id] = state
        return .applied
    }

    private func acceptsSchemaVersion(_ schemaVersion: Int) -> Bool {
        return schemaVersion == CodexDockConstants.Dock.streamSchemaVersion
    }

    private func acceptsStreamContract(
        _ update: ThreadCardStreamUpdateDTO,
        expectedSourceHostID: String? = nil
    ) -> Bool {
        guard let sourceHostID = nonEmpty(update.sourceHostID),
              update.identityVersion == ProjectionEnvelope.identityVersion,
              update.projectionEngineVersion == ProjectionEnvelope.engineVersion,
              update.scope == ProjectionEnvelope.scope,
              nonEmpty(update.viewParamsKey) != nil,
              update.order == ProjectionEnvelope.order else {
