        }
        if let expectedSourceHostID,
           expectedSourceHostID != sourceHostID {
            return false
        }
        guard update.view == expectedView else {
            return false
        }
        switch update.kind {
        case .snapshot:
            guard let complete = update.complete,
                  let totalRows = update.totalRows,
                  let window = update.window else {
