public struct AppLifecycleSnapshot: Equatable, Sendable {
    public let phase: AppLifecyclePhase
    public let resumeGeneration: Int

    public var allowsForegroundWork: Bool {
        switch phase {
        case .active, .foregroundResuming:
            return true
